  if((Boolean(candidate.listing_hint) || Boolean(candidate.third_party_hint)) && !Boolean(candidate.official_evidence_page)) continue;
  const status=Number(response.json?.statusCode || response.json?.status || 0);
  if(!(status>=200&&status<400)) continue;
  const pathname=pathnameFromUrl(candidateUrl);
  if(BLOCKED_PATH.test(pathname)) continue;
  if(BLOCKED_EXTENSION.test(pathname)) continue;
  const contentType=String(response.json?.headers?.['content-type'] || response.json?.headers?.['Content-Type'] || '').trim();
  if(contentType && !HTML_TYPE.test(contentType)) continue;
  const domainSignal=Boolean(candidate.domain_signal);
  const titleSignal=Boolean(candidate.title_signal);
  const snippetSignal=Boolean(candidate.snippet_signal);
  const clueCandidate=Boolean(candidate.clue_candidate);
  const officialEvidencePage=Boolean(candidate.official_evidence_page);
  if(!domainSignal && !(titleSignal && snippetSignal) && !clueCandidate && !officialEvidencePage) continue;
  accepted.push({
    best_url:candidateUrl,
    canonical_domain:domain
  });
}
const chosen=accepted[0];
if(!chosen){
  return {json:{best_url:'',canonical_domain:''}};
}
return {json:{
  best_url:chosen.best_url,
  canonical_domain:chosen.canonical_domain
}};

function stripFences(value){
  const fence=String.fromCharCode(96).repeat(3);
  return String(value||'').split(fence+'json').join('').split(fence).join('').trim();
}
function normalizeCandidateUrl(value){
  const raw=String(value||'').trim();
  if(!raw)return '';
  const withProtocol=/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)?raw:'https://'+raw;
  const match=withProtocol.match(/^(?:https?:\/\/)?([^\/?#]+)([^?#]*)/i);
  if(!match) return '';
  const host=String(match[1]||'').toLowerCase().trim();
  if(!host||!host.includes('.')) return '';
  let pathname=String(match[2]||'/').replace(/\/+/g,'/');
  if(!pathname.startsWith('/')) pathname='/' + pathname;
  if(pathname.length>1 && pathname.endsWith('/')) pathname=pathname.slice(0,-1);
  return 'https://' + host + (pathname||'/');
}
function registrableDomain(hostname){
  const labels=String(hostname||'').split('.').filter(Boolean);
  if(labels.length>=3&&labels[labels.length-1]==='sg'&&['com','org','net','edu','gov'].includes(labels[labels.length-2])) return labels.slice(-3).join('.');
  return labels.length>=2 ? labels.slice(-2).join('.') : (labels[0]||'');
}
function pathnameFromUrl(value){
  const normalized=normalizeCandidateUrl(value);
  if(!normalized) return '/';
  const raw=String(normalized || value || '');
  const match=raw.match(/^https?:\/\/[^/]+(\/[^?#]*)/i);
  return String(match?.[1] || '/').toLowerCase().replace(/\/+/g,'/') || '/';
}
function normalizeRoot(value){
  const normalized=normalizeCandidateUrl(value);
  if(!normalized)return '';
  const match=normalized.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  const hostname=String(match?.[1]||'').toLowerCase().trim();
  if(!hostname) return '';
  const utilitySubdomain=/^(?:mypolicy|connect|portal|login|account|accounts)./i.test(hostname);
  const rootHost=utilitySubdomain ? registrableDomain(hostname) : hostname;
  return rootHost ? ('https://'+rootHost+'/') : '';
}
function canonicalDomain(value){
  const normalized=normalizeCandidateUrl(value);
  const match=normalized.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  return String(match?.[1]||'').replace(/^www\./i,'').toLowerCase().trim();
}
function compact(value){
  return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,'');
}
function hasLegalEntityMarkers(value){
  return /\b(?:pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation|holdings?|group)\b/i.test(String(value||''));
}
function legalEntitySelectionScore(candidate, inputName){
  const title=String(candidate.title || '');
  const snippet=String(candidate.snippet || '');
  const url=String(candidate.url || candidate.evidence_url || '');
  const compactInput=compact(inputName);
  const simplifiedInput=compact(String(inputName || '').replace(/\b(?:pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation|holdings?|group)\b/gi,' '));
  const compactTitle=compact(title);
  const compactSnippet=compact(snippet);
  const rootDomain=canonicalDomain(candidate.homepage_root || candidate.url || '');
  const rootLabel=compact(rootDomain.split('.').slice(0,1).join(''));
  let score=0;
  if(compactInput && compactTitle.includes(compactInput)) score += 8;
  if(compactInput && compactSnippet.includes(compactInput)) score += 6;
  if(simplifiedInput && rootLabel && (rootLabel.includes(simplifiedInput) || (simplifiedInput.startsWith('singapore') && rootLabel.includes('sg' + simplifiedInput.replace(/^singapore/, ''))))) score += 6;
  if(/(?:\/(?:about|about-us)(?:\/|$)|\/about\/group-of-companies(?:\/|$))/i.test(url)) score += 3;
  if(Boolean(candidate.corporate_signal)) score += 2;
  if(Boolean(candidate.root_candidate)) score += 1;
  if(/\b(?:center|centre|clinic|hospital|medical centre)\b/i.test(title) && compactInput && !compactTitle.includes(compactInput)) score -= 4;
  return score;
}
function homepageSelectionScore(candidate, preferCorporateRoot){
  let score=Number(candidate.evidence_score || 0);
  if(Boolean(candidate.domain_signal)) score += 2;
  if(Boolean(candidate.title_signal)) score += 1;
  if(Boolean(candidate.path_signal)) score += 2;
  if(Boolean(candidate.official_evidence_page)) score += 3;
  if(Boolean(candidate.utility_path_hint)) score -= 2;
  if(Boolean(candidate.clue_candidate)) score -= preferCorporateRoot ? 1 : 6;
  if(!preferCorporateRoot && !Boolean(candidate.root_candidate)) score += 2;
  if(preferCorporateRoot && Boolean(candidate.root_candidate)) score += 2;
  return score;
}
function shouldPreserveSelectedUrl(candidate, selectedUrl){
  const pathname=pathnameFromUrl(selectedUrl);
  if(pathname === '/' || !pathname) return false;
  if(Boolean(candidate.utility_path_hint) || /(?:\/(?:contact|contact-us|get-in-touch|about|about-us|privacy|terms|policy|faq|faqs|login|log-in|signin|sign-in|account|accounts|portal|careers?|jobs?|investor-relations|ir)\b)/i.test(pathname)) return false;
  const localeLanding=/^\/(?:[a-z]{2}(?:-[a-z]{2})?)(?:\/(?:[a-z]{2}(?:-[a-z]{2})?(?:\.html?)?|index(?:\.html?)?))?$/i.test(pathname);
  return localeLanding && Boolean(candidate.corporate_signal || candidate.domain_signal || candidate.official_evidence_page);
}
function shouldUseSelectedScrapeUrl(candidate, selectedUrl){
  const pathname=pathnameFromUrl(selectedUrl);
  if(pathname === '/' || !pathname) return false;
  if(/(?:\/(?:latest-updates?|news|blog|article|articles|event|events|press|media)\b|(?:^|[-\/])is-now-open(?:[-\/]|$))/i.test(pathname)) return false;
  if(Boolean(candidate.utility_path_hint) && !/(?:\/(?:about|about-us)\b)/i.test(pathname)) return false;
  return Boolean(candidate.official_evidence_page);
}

const source=$('Pick First Valid Homepage').first().json || {};
const candidates=Array.isArray(source.candidates) ? source.candidates : [];
const normalizeInput=(()=>{try{return $('Normalize Input').first().json || {};}catch{return {};}})();
const companyName=String(normalizeInput.company_name || '').trim();
const preferCorporateRoot=Boolean(normalizeInput.prefer_corporate_root) && hasLegalEntityMarkers(companyName);
const inputItem=$input.first()?.json || {};
const content=String(inputItem.choices?.[0]?.message?.content || inputItem.body?.choices?.[0]?.message?.content || '').trim();
let parsed={};
try{ parsed=JSON.parse(stripFences(content)); }catch{}
const requestedRaw=[];
if(Object.prototype.hasOwnProperty.call(parsed,'selected')) requestedRaw.push(parsed.selected);
if(Array.isArray(parsed.alternates)) requestedRaw.push(...parsed.alternates);
const byUrl=new Map();
const byRoot=new Map();
for(const candidate of candidates){
  const normalizedUrl=normalizeCandidateUrl(candidate.url || candidate.homepage_root || '');
  const root=normalizeRoot(normalizedUrl || candidate.homepage_root || '');
  if(normalizedUrl) byUrl.set(normalizedUrl,candidate);
  if(root && !byRoot.has(root)) byRoot.set(root,candidate);
}
const ordered=[];
const seen=new Set();
for(const raw of requestedRaw){
  const normalized=normalizeCandidateUrl(raw);
  const root=normalizeRoot(raw);
  const candidate=(normalized && byUrl.get(normalized)) || (root && byRoot.get(root));
  if(candidate){
    const key=String(candidate.url || candidate.homepage_root || '');
    if(!seen.has(key)){
      ordered.push(candidate);
      seen.add(key);
    }
  }
}
const explicitBlank=Object.prototype.hasOwnProperty.call(parsed,'selected') && !normalizeCandidateUrl(parsed.selected || '') && (!Array.isArray(parsed.alternates) || parsed.alternates.every((value)=>!normalizeCandidateUrl(value || '')));
if(explicitBlank || (!ordered.length && Object.keys(parsed).length)){
  return [{json:{best_url:'',homepage_root:'',scrape_url:'',evidence_url:'',canonical_domain:'',title:'',snippet:'',domain_signal:false,title_signal:false,snippet_signal:false,listing_hint:false,third_party_hint:false,clue_candidate:false,official_evidence_page:false}}];
}
for(const candidate of candidates){
  const key=String(candidate.url || candidate.homepage_root || '');
  if(!seen.has(key)){
    ordered.push(candidate);
    seen.add(key);
  }
}
if(ordered.length > 1){
  if(preferCorporateRoot){
    ordered.sort((a,b)=>{
      const scoreDiff=legalEntitySelectionScore(b, companyName) - legalEntitySelectionScore(a, companyName);
      if(scoreDiff) return scoreDiff;
      return homepageSelectionScore(b, preferCorporateRoot) - homepageSelectionScore(a, preferCorporateRoot);
    });
  } else {
    ordered.sort((a,b)=> homepageSelectionScore(b, preferCorporateRoot) - homepageSelectionScore(a, preferCorporateRoot));
  }
}
if(!ordered.length){
  return [{json:{best_url:'',homepage_root:'',scrape_url:'',evidence_url:'',canonical_domain:'',title:'',snippet:'',domain_signal:false,title_signal:false,snippet_signal:false,listing_hint:false,third_party_hint:false,clue_candidate:false,official_evidence_page:false}}];
}
return ordered.map((candidate)=>{
  const selectedUrl=normalizeCandidateUrl(candidate.url || candidate.homepage_root || '');
  const rootUrl=normalizeRoot(selectedUrl || candidate.homepage_root || '');
  const finalUrl=shouldPreserveSelectedUrl(candidate, selectedUrl) ? selectedUrl : rootUrl;
  const scrapeUrl=shouldUseSelectedScrapeUrl(candidate, selectedUrl) ? selectedUrl : finalUrl;
  return {json:{
    best_url:finalUrl,
    homepage_root:rootUrl,
    scrape_url:scrapeUrl,
    evidence_url:selectedUrl || rootUrl,
    canonical_domain:String(canonicalDomain(finalUrl)||candidate.canonical_domain||''),
    title:String(candidate.title||''),
    snippet:String(candidate.snippet||''),
    domain_signal:Boolean(candidate.domain_signal),
    title_signal:Boolean(candidate.title_signal),
    snippet_signal:Boolean(candidate.snippet_signal),
    listing_hint:Boolean(candidate.listing_hint),
    third_party_hint:Boolean(candidate.third_party_hint),
    clue_candidate:Boolean(candidate.clue_candidate),
    official_evidence_page:Boolean(candidate.official_evidence_page)
  }};
});
